package com.rekluzlabs.makokolorize.ui.screensimport android.graphics.Bitmapimport android.net.Uriimport androidx.compose.foundation.Imageimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.aspectRatioimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.heightimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.rememberScrollStateimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.foundation.verticalScrollimport androidx.compose.material3.Buttonimport androidx.compose.material3.CircularProgressIndicatorimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.OutlinedButtonimport androidx.compose.material3.Textimport androidx.compose.material3.TextButtonimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.rememberCoroutineScopeimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.graphics.asImageBitmapimport androidx.compose.ui.layout.ContentScaleimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.res.painterResourceimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.text.style.TextAlignimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport com.rekluzlabs.makokolorize.Rimport com.rekluzlabs.makokolorize.data.image.ImageRepositoryimport com.rekluzlabs.makokolorize.domain.ColorizeUseCaseimport com.rekluzlabs.makokolorize.domain.RunConfigimport com.rekluzlabs.makokolorize.ui.components.AppProgressIndicatorimport kotlinx.coroutines.Jobimport kotlinx.coroutines.launchimport android.util.Log@Composablefun MainScreen(    imageUri: Uri,    onResultReady: (RunConfig) -> Unit,    onBack: () -> Unit) {    val context = LocalContext.current    val scope = rememberCoroutineScope()    val scrollState = rememberScrollState()    var bitmap by remember { mutableStateOf<Bitmap?>(null) }    var loadingBitmap by remember { mutableStateOf(true) }    var processing by remember { mutableStateOf(false) }    var progress by remember { mutableStateOf(0f) }    var error by remember { mutableStateOf<String?>(null) }    var job by remember { mutableStateOf<Job?>(null) }    var lastConfig by remember { mutableStateOf(RunConfig()) }    var showPreflightSheet by remember { mutableStateOf(false) }    LaunchedEffect(imageUri) {        loadingBitmap = true        error = null        val repo = ImageRepository(context)        repo.loadBitmap(imageUri)            .onSuccess {                bitmap = it                loadingBitmap = false            }            .onFailure { e ->                Log.e("MainScreen", "Failed to load bitmap", e)                error = "Failed to load image: ${e.localizedMessage}"                loadingBitmap = false            }    }    Column(        modifier = Modifier            .fillMaxSize()            .padding(24.dp)            .verticalScroll(scrollState),        horizontalAlignment = Alignment.CenterHorizontally    ) {        Image(            painter = painterResource(id = R.mipmap.ic_launcher_foreground),            contentDescription = "App Logo",            modifier = Modifier                .size(80.dp)                .clip(RoundedCornerShape(16.dp))        )        Spacer(modifier = Modifier.height(12.dp))        Text(            text = "makokolorize",            fontSize = 20.sp,            fontWeight = FontWeight.Bold        )        Spacer(modifier = Modifier.height(24.dp))        if (loadingBitmap) {            CircularProgressIndicator(modifier = Modifier.padding(32.dp))            Text("Preparing image...", fontSize = 14.sp)        } else if (bitmap != null) {            Image(                bitmap = bitmap!!.asImageBitmap(),                contentDescription = "Selected image",                modifier = Modifier                    .fillMaxWidth()                    .aspectRatio(1f)                    .clip(RoundedCornerShape(12.dp)),                contentScale = ContentScale.Fit            )        } else if (error != null) {            Text(                text = error!!,                color = MaterialTheme.colorScheme.error,                textAlign = TextAlign.Center,                modifier = Modifier.padding(16.dp)            )        }        Spacer(modifier = Modifier.height(16.dp))        if (processing) {            AppProgressIndicator(progress = progress)            Spacer(modifier = Modifier.height(8.dp))            Text("${(progress * 100).toInt()}%", fontSize = 14.sp)            Spacer(modifier = Modifier.height(12.dp))            OutlinedButton(onClick = {                job?.cancel()                processing = false                progress = 0f                error = null            }) {                Text("Cancel")            }        } else if (bitmap != null) {            Button(                onClick = { showPreflightSheet = true }            ) {                Text("Begin Colorization")            }        }        Spacer(modifier = Modifier.height(16.dp))        if (!processing) {            TextButton(onClick = onBack) {                Text("Back")            }        }    }    if (showPreflightSheet) {        PreflightSheet(            initialConfig = lastConfig,            onDismiss = { showPreflightSheet = false },            onStart = { config ->                showPreflightSheet = false                lastConfig = config                val bm = bitmap ?: return@PreflightSheet                processing = true                progress = 0f                error = null                job = scope.launch {                    val useCase = ColorizeUseCase(context)                    useCase.execute(bm, { p -> progress = p }, config)                        .onSuccess { result ->                            processing = false                            onResultReady(config)                        }                        .onFailure { e ->                            error = e.message                            processing = false                        }                }            }        )    }}